use vstd::prelude::*;

verus! {

// Specification function: checks if a character is a lowercase ASCII letter
spec fn is_lowercase_char(c: char) -> bool {
    'a' <= c && c <= 'z'
}

// Specification function: checks if all characters in a sequence are lowercase
spec fn all_chars_lowercase(v: Seq<char>) -> bool {
    forall|i: int| 0 <= i < v.len() ==> is_lowercase_char(v[i])
}

// Specification function: defines what "all lowercase" means for the problem
spec fn is_all_lowercase(v: Seq<char>) -> bool {
    v.len() > 0 && all_chars_lowercase(v)
}

// Helper function to check if all characters are lowercase
fn check_all_lowercase(v: &Vec<char>) -> (result: bool)
    ensures
        result == is_all_lowercase(v@)
{
    if v.len() == 0 {
        return false;
    }
    
    let mut i: usize = 0;
    while i < v.len()
        invariant
            0 <= i <= v.len(),
            v.len() > 0,
            forall|j: int| 0 <= j < i ==> is_lowercase_char(v@[j])
    {
        let c = v[i];
        if !(c >= 'a' && c <= 'z') {
            assert(!is_lowercase_char(v@[i as int]));
            assert(!all_chars_lowercase(v@));
            return false;
        }
        i += 1;
    }
    
    assert(forall|j: int| 0 <= j < v@.len() ==> is_lowercase_char(v@[j]));
    assert(all_chars_lowercase(v@));
    true
}

// Main function
fn solve(input: Vec<char>) -> (result: Vec<char>)
    ensures
        result.len() == 1,
        is_all_lowercase(input@) ==> result@[0] == 'a',
        !is_all_lowercase(input@) ==> result@[0] == 'A',
        result@[0] == 'a' || result@[0] == 'A'
{
    let is_lower = check_all_lowercase(&input);
    
    let mut output = Vec::new();
    
    if is_lower {
        output.push('a');
        assert(output@[0] == 'a');
    } else {
        output.push('A');
        assert(output@[0] == 'A');
    }
    
    assert(output.len() == 1);
    output
}

} // verus!